// contracts/examples/handoff.json 을 그대로 돌려주는 가짜 team3-handoff. 늘 HTTP 200 (계약).
const EX = {"response_ok": {"ticket": {"ticket_id": "T-2003", "priority": "high", "duplicate": false}, "reason": "", "dlq": false, "alert": true, "extras": {"screen": "ok", "slack": "skipped", "jira": "skipped"}, "handoff_ms": 412}, "response_duplicate": {"ticket": {"ticket_id": "T-2003", "priority": "high", "duplicate": true}, "reason": "", "dlq": false, "alert": false, "extras": {"screen": "skipped", "slack": "skipped", "jira": "skipped"}, "handoff_ms": 95}, "response_tickets_down": {"ticket": null, "reason": "tickets_down", "dlq": true, "alert": true, "extras": {"screen": "skipped", "slack": "skipped", "jira": "skipped"}, "handoff_ms": 2950}};
const body = $json.body ?? {};
const pick = { tickets_down: EX.response_tickets_down, duplicate: EX.response_duplicate };
const out = JSON.parse(JSON.stringify(pick[body.simulate] ?? EX.response_ok));
if (out.ticket && body.priority) out.ticket.priority = body.priority;   // 요청의 priority를 그대로 비춰 줌
if (!pick[body.simulate]) out.alert = body.priority === 'high';         // 긴급만 알림 (00-DESIGN.md 3.4절)
return [{ json: out }];
